#include <math.h>
const int sense = {{ADC}};
const float supply = {{REF}};

void setup() {
  Serial.begin(9600);
  {{ADC_SETUP}}
}

void loop() {
  float v = {{READV}};
  if (v > 0.02f && v < supply - 0.02f) {
    float r = 10000.0f * v / (supply - v);
    float t = 1.0f / (1.0f / 298.15f + log(r / 10000.0f) / 3950.0f) - 273.15f;
    Serial.println(t, 1);
  } else {
    Serial.println("ADC out of range");
  }
  delay(500);
}
